use std :: path :: { Path , PathBuf } ; use std :: time :: SystemTime ; use anyhow :: { Context , Result } ; use crate :: cli :: LogsArgs ; # [doc = " Entry point called from the CLI handler."] pub async fn run (args : LogsArgs , log_dir : PathBuf) -> Result < () > { if args . list { list (& log_dir) . await } else { let file = match args . file { Some (path) => path , None => latest (& log_dir) . await ? , } ; tail (& file , args . lines , args . no_follow) . await } }